'use server';

import { revalidatePath } from 'next/cache';

// Mock state to represent a user's notification preference in a database
let notificationsEnabled = false;

export async function getNotificationPreference() {
  return notificationsEnabled;
}

export async function toggleNotificationPreference() {
  // Toggle the preference in the "database"
  notificationsEnabled = !notificationsEnabled;

  // Revalidate the current path to refresh the page data without redirecting
  revalidatePath('/');
}

import { getNotificationPreference, toggleNotificationPreference } from './actions';

export default async function Home() {
  const isEnabled = await getNotificationPreference();

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Settings</h1>

      <p>
        Notifications are currently: <strong>{isEnabled ? 'ON' : 'OFF'}</strong>
      </p>

      <form action={toggleNotificationPreference}>
        <button 
          type="submit" 
          style={{ 
            padding: '0.5rem 1rem', 
            cursor: 'pointer', 
            background: '#0070f3', 
            color: 'white', 
            border: 'none', 
            borderRadius: '4px' 
          }}
        >
          Toggle Notification Preference
        </button>
      </form>
    </main>
  );
}
